message.content:
{
  "title": "The Clockwork Rescue",
  "gate_token": "frksoAYAhxAmd-frAHTANg",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara studies a cracked map of the ruined city.",
      "visual_description": "Mara the Cartographer leans over a weathered table, her ink-stained coat brushing scattered papers, a brass compass glowing faintly in dim lamplight.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The Oracle Lamp flickers a dire warning.",
      "visual_description": "The Oracle Lamp sits on a stone ledge, its single flame-eye pulsing as shadows dance across crumbling walls.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "Glass Diver peers through a shattered window into the city.",
      "visual_description": "Glass Diver presses his diving helmet against a jagged window frame, his coat reflecting distant torchlight from the ruined streets.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 4,
      "caption": "Tin Fox scampers ahead to scout the castle gates.",
      "visual_description": "Tin Fox darts through rubble, its key-wind tail ticking, blue glass eyes scanning the massive iron gates flanked by faded royal banners.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 5,
      "caption": "Sleeping Tax Collector snores behind a ledger at the gatehouse.",
      "visual_description": "The Sleeping Tax Collector dozes on a heap of stamped papers, ledger book as a pillow, oblivious to the creaking gate.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 6,
      "caption": "Mara marks a safe path past the patrols on the map.",
      "visual_description": "Mara traces a route with her compass, avoiding armored patrols that march in the distance, their torches bobbing.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 7,
      "caption": "Oracle Lamp glows brighter near a cursed tower.",
      "visual_description": "The Oracle Lamp casts a flickering light on a twisted spire, its flame-eye narrowing as if sensing magic.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 8,
      "caption": "Glass Diver swims through a mirror into the tower's base.",
      "visual_description": "Glass Diver steps through a tall mirror, his helmet rippling like water, emerging in a dusty chamber filled with old banners.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 9,
      "caption": "Tin Fox finds a hidden passage behind a tapestry.",
      "visual_description": "Tin Fox nudges a frayed tapestry aside, revealing a narrow stone corridor, its tail winding faster.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 10,
      "caption": "Mara consults the Oracle Lamp at a crossroads.",
      "visual_description": "Mara holds the Oracle Lamp up at a three-way junction, its flame pointing left as she scribbles notes on her map.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 11,
      "caption": "Sleeping Tax Collector stirs but returns to sleep.",
      "visual_description": "The Sleeping Tax Collector murmurs in his sleep, one eye opening briefly then closing, papers rustling around him.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 12,
      "caption": "Glass Diver confronts a magic door that shifts patterns.",
      "visual_description": "Glass Diver faces a door with swirling runes that rearrange themselves, his reflection distorting on its surface.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 13,
      "caption": "Tin Fox triggers a trap but escapes unharmed.",
      "visual_description": "Tin Fox leaps over a pressure plate as a stone block crashes behind him, landing silently on metal paws.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 14,
      "caption": "Mara and Oracle Lamp navigate a hall of mirrors.",
      "visual_description": "Mara walks carefully through a mirrored corridor, the Oracle Lamp's light reflecting infinitely, her compass steady.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 15,
      "caption": "Glass Diver retrieves the captive from a mirrored cell.",
      "visual_description": "Glass Diver reaches through a mirror wall to pull out a huddled figure, his helmet gleaming in the dim cell.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 16,
      "caption": "The group regroups as Tin Fox signals the escape route.",
      "visual_description": "Mara, Glass Diver, and the rescued figure follow Tin Fox through a narrow alley, the Oracle Lamp lighting the way.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 17,
      "caption": "Sleeping Tax Collector wakes and blocks the bridge.",
      "visual_description": "The Sleeping Tax Collector stands groggily on a stone bridge, ledger held up, papers fluttering in the wind.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 18,
      "caption": "The team crosses the bridge and escapes the city.",
      "visual_description": "Mara leads the group across the bridge, Glass Diver supporting the rescued figure, Tin Fox prancing ahead, as the Oracle Lamp's flame dims in the dawn light.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    }
  ]
}

